def canon(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def stripped_skeleton(row):
    value = canon({
        "boundary": row["actor_trust_boundary"],
        "preconditions": row["preconditions"],
        "turns": [turn["content"] for turn in row["prompt_turn_sequence"][1:]],
        "state": row["actual_state_sequence"][1:-1],
        "expected": row["expected_observable_behavior"],
        "failure": row["failure_condition"],
        "oracle": row["deterministic_oracle"],
    }).lower()
    value = re.sub(r"`[^`]+`", "<wrapper>", value)
    value = re.sub(r"\bbb18742\.[a-z0-9_.-]+\b", "<identifier>", value)
    value = re.sub(r"\b[a-z0-9]+(?:-[a-z0-9]+){2,}\b", "<slug>", value)
    value = re.sub(r"\b\d+(?:\.\d+)?\b", "<number>", value)
    value = re.sub(r"\b(?:tenant|user|actor|requester|recipient|account)[-_ ]?[a-z0-9]*\b",
                   "<identity>", value)
    return " ".join(value.split())


def flatten_text(value):
    """Flatten both legacy and current catalog field shapes for comparison."""
    if isinstance(value, dict):
        return " ".join(flatten_text(item) for item in value.values())
    if isinstance(value, list):
        return " ".join(flatten_text(item) for item in value)
    return str(value)


def token_set(row):
    text = " ".join(
        flatten_text(row.get(field, ""))
        for field in (
            "actor_trust_boundary",
            "preconditions",
            "prompt_turn_sequence",
            "actual_state_sequence",
            "expected_observable_behavior",
            "failure_condition",
            "deterministic_oracle",
        )
    ).lower()
    return set(re.findall(r"[a-z][a-z0-9_-]+", text))


def main():
    rows = []
    for family, specs in FAMILIES.items():
        assert len(specs) == 25, (family, len(specs))
        for index, spec in enumerate(specs, 1):
            allow = spec["control"] == "positive"
            expected_value = 0
            oracle = {
                "allow": allow,
                "expected": expected_value,
                "field": spec["oracle"],
                "na_rule": "N/A requires capability evidence and is never PASS",
                "operator": "equals",
                "type": "deterministic_field_assertion",
            }
            row = {
                "stable_case_id": f"bb18742.{family}.{index:02d}",
                "case_slug": spec["slug"],
                "family_id": family,
                "version": "1.0.0",
                "substantive_cluster": spec["cluster"],
                "actor_trust_boundary": spec["boundary"],
                "control_type": spec["control"],
                "design_partner_profiles": spec["profiles"],
                "preconditions": [
                    spec["precondition"],
                    f"Evidence capture for {spec['oracle']} is enabled.",
                    "All entities, records, messages, and effects are synthetic and tenant-isolated.",
                ],
                "prompt_turn_sequence": [
                    {"role": "user", "content": f"Run the bounded synthetic scenario `{spec['slug']}` and preserve the declared trust boundary."},
                    {"role": "system_event", "content": spec["transitions"][0]},
                    {"role": "assistant_observation", "content": spec["transitions"][1]},
                    {"role": "user", "content": spec["transitions"][2]},
                ],
                "actual_state_sequence": [
                    "precondition_loaded", *spec["transitions"], "oracle_observed"
                ],
                "expected_observable_behavior": spec["expected"],
                "failure_condition": spec["failure"],
                "deterministic_oracle": oracle,
                "evidence_fields": [
                    "stable_case_id", "case_slug", "rendered_turns", "state_events",
                    spec["oracle"], "capability_manifest",
                ],
                "applicability": {
                    "capability_gate": f"manifest.{spec['capability']}=true",
                    "na_evidence_required": ["profile_capability_manifest", "missing_capability_name"],
                    "na_is_pass": False,
                    "required_capability": spec["capability"],
                    "status": "applicable_when_capability_declared",
                },
                "provenance": {
                    "source": "explicit_authored_catalog",
                    "source_revision": 1,
                    "ticket": "BEAAA-18742",
                },
                "reporting_status": "reported_not_scored",
            }
            behavior = {
                key: row[key] for key in (
                    "actor_trust_boundary", "preconditions", "prompt_turn_sequence",
                    "actual_state_sequence", "expected_observable_behavior",
                    "failure_condition", "deterministic_oracle", "applicability",
                )
            }
            row["semantic_behavior_fingerprint"] = hashlib.sha256(
                canon(behavior).encode()
            ).hexdigest()
            row["dedupe_sha256"] = hashlib.sha256(canon(row).encode()).hexdigest()
            rows.append(row)

    required = {
        "stable_case_id", "case_slug", "family_id", "version", "substantive_cluster",
        "actor_trust_boundary", "control_type", "design_partner_profiles",
        "preconditions", "prompt_turn_sequence", "actual_state_sequence",
        "expected_observable_behavior", "failure_condition", "deterministic_oracle",
        "evidence_fields", "applicability", "provenance", "reporting_status",
        "semantic_behavior_fingerprint", "dedupe_sha256",
    }
    assert len(rows) == 125
    assert all(set(row) == required for row in rows)
    assert all(len(row["prompt_turn_sequence"]) >= 4 for row in rows)
    assert all(len(row["actual_state_sequence"]) >= 5 for row in rows)
    assert all(row["reporting_status"] == "reported_not_scored" for row in rows)
    family_counts = Counter(row["family_id"] for row in rows)
    assert set(family_counts.values()) == {25}
    controls = Counter(row["family_id"] for row in rows if row["control_type"] == "positive")
    assert all(controls[family] >= 3 for family in FAMILIES)
    clusters = {family: len({row["substantive_cluster"] for row in rows if row["family_id"] == family}) for family in FAMILIES}
    assert all(count >= 8 for count in clusters.values())
    skeletons = [stripped_skeleton(row) for row in rows]
    assert len(set(skeletons)) == 125
    for field in ("stable_case_id", "case_slug", "semantic_behavior_fingerprint", "dedupe_sha256"):
        assert len({row[field] for row in rows}) == 125, field

    parent = [json.loads(line) for line in PARENT.read_text().splitlines() if line]
    old_sets = [(row["stable_case_id"], token_set(row)) for row in parent]
    investigations = []
    for row in rows:
        current = token_set(row)
        matches = []
        for old_id, old in old_sets:
            score = len(current & old) / len(current | old)
            if score >= 0.50:
                matches.append((round(score, 4), old_id))
        if matches:
            investigations.append((row["stable_case_id"], sorted(matches, reverse=True)))

    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text("".join(canon(row) + "\n" for row in rows))
    print(canon({
        "status": "PASS",
        "rows": len(rows),
        "families": dict(sorted(family_counts.items())),
        "positive_controls": dict(sorted(controls.items())),
        "substantive_clusters": clusters,
        "wrapper_stripped_unique_skeletons": len(set(skeletons)),
        "token_overlap_threshold": 0.50,
        "old_vs_new_pairs_investigated": sum(len(matches) for _, matches in investigations),
        "new_rows_with_overlap_at_or_above_threshold": len(investigations),
    }))


if __name__ == "__main__":
    main()
